<template>
  <div class="student-center-route"><LiveStudentSupport v-if="route.query.demo!=='1'"/><AppLayout v-else><main class="student-center">
    <div class="student-notice"><span>{{demo?'演示模式 · 使用示例训练记录，操作只保存在当前浏览器。示例时间：2026年10月3日。':'学生详情与能力证据接口尚未接入。'}}</span><RouterLink :to="{path:route.path,query:{...q,demo:demo?undefined:'1'}}">{{demo?'切换真实数据':'查看演示效果'}}</RouterLink></div>
    <RouterLink v-if="typeof q.returnTo==='string' &amp;&amp; /^\/teacher\/analytics(\?|$)/.test(q.returnTo)" :to="q.returnTo" class="source-return">返回数据分析</RouterLink>
    <p v-if="q.analyticsFrom" class="student-muted">分析来源范围：{{q.analyticsFrom}} ～ {{q.analyticsTo}} · {{q.classIds?'指定班级':'全部班级'}} · 当前有效账号。<button @click="clearFilters">清除来源筛选</button></p>
    <div v-if="data.error" class="student-load-error" role="alert">{{data.error}}<button @click="refresh++">重试读取</button></div>
    <template v-if="!detail">
      <header class="student-heading"><div><h1>学生中心</h1><p>查找学生，查看个人训练、能力与任务情况</p></div></header>
      <div class="student-filters"><label>班级<select aria-label="班级" :value="q.classId||''" @change="set('classId',$event.target.value)"><option value="">全部班级</option><option v-for="c in classDefinitions" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label class="student-search">搜索<input :value="q.search||''" placeholder="搜索姓名或学号" @input="set('search',$event.target.value)"/></label><label>排序<select aria-label="排序" :value="q.sort||'attention'" @change="set('sort',$event.target.value)"><option value="attention">需要关注优先</option><option value="recent">最近有效训练</option><option value="count">训练次数</option><option value="name">姓名</option></select></label><button :aria-expanded="advanced" aria-controls="student-more-filters" @click="advanced=!advanced">更多筛选{{filterChips.length?'（'+filterChips.length+'）':''}}</button></div>
      <div v-if="advanced" id="student-more-filters" class="student-filters student-advanced"><label>目标岗位<select aria-label="目标岗位" :value="q.position||''" @change="set('position',$event.target.value)"><option value="">全部岗位</option><option v-for="p in positions" :key="p">{{p}}</option></select></label><label>最近训练<select aria-label="最近训练" :value="q.recent||''" @change="set('recent',$event.target.value)"><option value="">不限</option><option value="7">近7天有有效训练</option><option value="30">近30天有有效训练</option><option value="none">当前周期无有效训练</option></select></label><label>训练报告表现变化<select aria-label="训练报告表现变化" :value="q.growth||''" @change="set('growth',$event.target.value)"><option value="">全部变化</option><option v-for="s in growthStatuses" :key="s">{{s}}</option></select></label><label>跟进条件<select aria-label="跟进条件" :value="q.concern||''" @change="set('concern',$event.target.value)"><option value="">不限</option><option value="overdue">有逾期未完成任务</option><option value="few">当前周期有效训练不足2次</option></select></label></div>
      <div v-if="filterChips.length" class="student-filter-chips"><button v-for="f in filterChips" :key="f.key" @click="set(f.key,'')" :aria-label="'移除'+f.label">{{f.label}} ×</button></div>
      <details class="student-rule"><summary>查看关注优先排序规则</summary><p>持续下降 → 逾期未完成 → 当前周期无有效训练 → 仅1次有效训练 → 其他学生。同等级按最近训练时间从早到晚排列，无训练记录优先；再按学号排序。能力差距暂不参与排序。</p></details>
      <div v-if="demo&&rows.length" class="student-table-scroll student-desktop-list"><table class="student-list-table"><thead><tr><th>学生</th><th>班级</th><th>目标岗位</th><th>{{periodLabel}}有效训练</th><th>训练报告表现变化</th><th>待完成任务</th><th>主要关注</th><th>最近有效训练</th><th>操作</th></tr></thead><tbody><tr v-for="s in pagedRows" :key="s.id"><td><strong>{{s.name}}</strong><small>{{s.number}}</small></td><td>{{s.className}}</td><td>{{s.position||'未设置'}}</td><td>{{s.count}}次</td><td>{{s.growth.status}}<small v-if="s.growthReason">{{s.growthReason}}</small></td><td>{{s.activeCount}}个待完成<small v-if="s.overdueCount" class="student-danger">{{s.overdueCount}}个逾期</small></td><td class="student-concern">{{s.concern||'暂无明确跟进事项'}}</td><td>{{s.last?formatDate(s.last):'暂无有效训练'}}</td><td><RouterLink :to="studentLink(s)">查看学生</RouterLink></td></tr></tbody></table></div>
      <ul v-if="demo&&rows.length" class="student-mobile-list"><li v-for="s in pagedRows" :key="s.id"><header><div><strong>{{s.name}}</strong><small>{{s.number}} · {{s.className}}</small></div><RouterLink :to="studentLink(s)">查看学生</RouterLink></header><p>{{s.growth.status==='持续下降'?s.concern:s.overdueCount?'有'+s.overdueCount+'个逾期未完成任务':s.concern||'暂无明确跟进事项'}}</p><p class="student-muted">最近有效训练：{{s.last?formatDate(s.last):'暂无'}}</p><details><summary>更多学生信息</summary><dl><dt>目标岗位</dt><dd>{{s.position||'未设置'}}</dd><dt>{{periodLabel}}有效训练</dt><dd>{{s.count}}次</dd><dt>报告表现变化</dt><dd>{{s.growth.status}}<small v-if="s.growthReason">{{s.growthReason}}</small></dd><dt>待完成任务</dt><dd>{{s.activeCount}}个（含{{s.overdueCount}}个逾期）</dd></dl></details></li></ul>
      <div v-if="!demo||!rows.length" class="student-empty"><h2>{{demo?'没有符合条件的学生':'尚未接入真实学生数据'}}</h2><p>{{demo?'调整筛选条件，或清除筛选重新查找。':'接入授权班级名单与训练报告后，这里将展示学生情况。'}}</p><button v-if="demo" @click="clearFilters">清除筛选</button></div>
      <div v-if="rows.length" class="student-pagination"><span>共{{rows.length}}名学生</span><button :disabled="page===1" @click="set('page',page-1)">上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page===pages" @click="set('page',page+1)">下一页</button></div>
    </template>
    <template v-else>
      <RouterLink class="student-back" :to="returnLink">{{returnInfo.label}}</RouterLink>
      <div v-if="!student" class="student-empty"><h1>{{demo?'学生不存在或不在可查看范围':'学生详情暂不可用'}}</h1><p>{{demo?'请返回学生中心，从有效班级名单中选择学生。':'真实学生详情接口尚未接入，未展示示例评分。'}}</p></div>
      <template v-else>
        <header class="student-heading"><div><h1>{{student.name}}</h1><p>学号 {{student.number}} · {{student.className}} · {{student.major}} · 目标岗位：{{student.position||'未设置'}}</p></div><div class="student-header-actions"><RouterLink v-if="headerAction" class="student-primary" :to="headerAction.to">{{headerAction.label}}</RouterLink><details v-if="tab==='ability'&&abilityPending.length&&canCreate"><summary>更多训练操作</summary><RouterLink :to="createLink(scope==='common'?ability:undefined)">另布置新训练</RouterLink></details></div><span v-if="!headerAction" class="student-muted">该学生暂无法在任务模块中选择</span></header>
        <nav class="student-tabs" aria-label="学生详情"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" :aria-current="tab===t.id?'page':undefined" @click="set('tab',t.id)">{{t.name}}</button></nav>
        <template v-if="tab==='overview'">
          <dl class="student-status"><div><dt>近30天有效训练</dt><dd>{{summary.count}}次</dd></div><div><dt>训练报告表现变化（近30天）</dt><dd>{{summary.growth.status}}</dd><small v-if="summary.growthReason">{{summary.growthReason}}</small></div><div><dt>待完成任务（含逾期）</dt><dd>{{summary.activeCount}}个</dd></div><div><dt>逾期未完成</dt><dd :class="{'student-danger':summary.overdueCount}">{{summary.overdueCount}}个</dd></div><div><dt>最近有效训练</dt><dd>{{summary.last?formatDate(summary.last):'暂无有效训练'}}</dd></div></dl>
          <section v-if="summary.concern||focusSnapshot?.gap<0" class="student-main-concern"><div><h2>当前主要关注</h2><p v-if="summary.concern">{{summary.concern}}</p><p v-if="focusSnapshot?.gap<0">与目标差距最大：{{abilityConcern}}</p><small v-if="focusSnapshot?.gap<0">仅描述当前差距，不代表训练优先顺序。</small></div><div v-if="focusSnapshot?.gap<0" class="student-concern-actions"><button @click="chooseAbility(focusSnapshot.ability.id)">查看依据</button><RouterLink v-if="focusPending.length" :to="existingTasksLink(focusPending,focusSnapshot.ability)">查看已有任务（{{focusPending.length}}）</RouterLink></div></section>
          <div class="student-overview-columns"><div>
            <section class="student-section"><header><h2>近期能力表现</h2><button class="student-text" @click="set('tab','ability')">查看能力成长</button></header><p class="student-muted">{{periodLabel}} · 最近最多3次同口径有效评分；刻度为已配置目标。</p><div v-for="s in commonSnapshots" :key="s.ability.id" class="student-ability-row"><button class="student-text" @click="chooseAbility(s.ability.id)">{{s.ability.name}}</button><div class="student-ability-track"><i v-if="s.current!==null" :style="{width:s.current+'%'}"></i><span v-if="s.target!==null" :style="{left:s.target+'%'}" :title="'目标'+s.target"></span></div><span :title="gapLabel(s)">{{s.current===null?'暂无评分':decimal(s.current)}}<small v-if="s.current!==null"> / {{s.target??'未设置目标'}}</small></span></div></section>
            <section class="student-section"><header><h2>最近训练</h2><RouterLink :to="recordsLink">查看全部训练记录</RouterLink></header><ul v-if="recentRecords.length" class="student-record-list"><li v-for="r in recentRecords.slice(0,5)" :key="r.id"><div><strong>{{r.content}}</strong><p>{{formatDate(r.completedAt)}} · {{r.type}} · {{r.position}}</p><small>{{r.valid?'有效训练':'无效记录'}} · {{r.source==='TEACHER_TASK'?'教师任务':'学生自主'}}</small></div><RouterLink v-if="r.reportAvailable" :to="reportLink(r)">查看报告</RouterLink><span v-else class="student-muted">报告不可访问</span></li></ul><p v-else class="student-empty">暂无训练记录。完成训练后可查看报告。</p></section>
          </div><section class="student-section student-current-tasks"><header><h2>待完成任务</h2><button class="student-text" @click="showTasks">查看任务历史</button></header><ul v-if="currentTasks.length" class="student-record-list"><li v-for="r in currentTasks.slice(0,4)" :key="r.task.id"><div><strong>{{r.task.title}}</strong><p>{{statusNames[r.execution.completionStatus]}} · {{r.execution.validAttemptCount||0}}次有效完成 / 要求{{r.task.minValidAttempts}}次</p><small :class="{'student-danger':r.overdue}">{{r.overdue?'逾期未完成 · ':''}}截止 {{formatDate(r.task.deadline)}}</small></div><RouterLink :to="taskLink(r.task)">查看任务</RouterLink></li></ul><p v-else class="student-empty">暂无待完成任务。</p></section></div>
        </template>
        <template v-else-if="tab==='ability'">
          <div class="student-filters"><label>时间范围<select aria-label="时间范围" :value="period" @change="set('period',$event.target.value)"><option value="7d">近7天</option><option value="30d">近30天</option><option value="90d">近90天</option><option value="semester">本学期</option></select></label><label v-if="historicalPositions.length">岗位<select aria-label="岗位" :value="abilityPosition" @change="set('abilityPosition',$event.target.value)"><option :value="student.position">{{student.position}}（当前岗位）</option><option v-for="p in historicalPositions" :key="p">{{p}}</option></select></label><span v-else class="student-static-field">当前岗位：{{student.position||'未设置'}}</span><label>能力<select aria-label="能力" :value="ability.id" @change="selectAbility($event.target.value)"><optgroup label="通用能力"><option v-for="a in abilityDefinitions.filter(a=>a.scope==='common')" :key="a.id" :value="a.id">{{a.name}}</option></optgroup><optgroup label="岗位能力"><option v-for="a in abilityDefinitions.filter(a=>a.scope==='role')" :key="a.id" :value="a.id">{{a.name}}</option></optgroup></select></label></div>
          <section class="student-section"><header><h2>{{ability.name}}</h2><button @click="evidenceOpen=true">查看能力证据</button></header><dl class="student-status"><div><dt>{{snapshot.sampleLabel}}</dt><dd>{{snapshot.current===null?'暂无有效评分':decimal(snapshot.current)}}</dd></div><div><dt>{{snapshot.target===null?'目标未设置':'演示目标'}}</dt><dd>{{snapshot.target??'未设置'}}</dd></div><div><dt>与目标差距</dt><dd>{{gapLabel(snapshot)}}</dd></div><div><dt>{{ability.name}}评分变化（{{periodLabel}}）</dt><dd>{{snapshot.growth.status}}</dd><small v-if="snapshot.growthReason">{{snapshot.growthReason}}</small></div><div><dt>可比有效记录</dt><dd>{{snapshot.records.length}}次</dd></div></dl><StudentAbilityChart :records="snapshot.records" :target="snapshot.target" :name="ability.name" @select="selectEvidence"/><p v-if="snapshot.excluded" class="student-muted">{{snapshot.excluded}}条记录未纳入：缺少该能力评分、无效记录或不属于当前可比阶段。</p><details class="student-rule"><summary>查看能力与成长计算口径</summary><p>当前值为当前连续评分阶段内最近最多3次有效评分的平均；1次记录显示最近一次评分。成长判断复用已有规则，至少6条同岗位、同模型、同版本记录，最早3次与最近3次平均比较；最近3次连续下降且累计下降至少5分时标记持续下降。没有足够记录时不补0分，也不推断成长。</p></details></section>
          <section class="student-section"><header><h2>训练记录与评分变化</h2></header><p class="student-muted">仅描述相邻可比记录之间的分差，不表示训练造成了能力变化。</p><div v-if="snapshot.records.length" class="student-table-scroll"><table><thead><tr><th>训练时间</th><th>训练内容</th><th>能力评分</th><th>与上次变化</th><th>来源</th><th>报告</th></tr></thead><tbody><tr v-for="r in pagedAbilityRecords" :key="r.id"><td>{{formatDate(r.completedAt)}}</td><td>{{r.content}}</td><td>{{decimal(r.abilityScore)}}</td><td>{{deltaLabel(r.delta,'首次记录')}}</td><td>{{r.source==='TEACHER_TASK'?'教师任务':'学生自主'}}</td><td><RouterLink v-if="r.reportAvailable" :to="reportLink(r)">查看报告</RouterLink><span v-else>不可访问</span></td></tr></tbody></table></div><p v-else class="student-empty">暂无可比能力记录。</p><div v-if="snapshot.records.length>15" class="student-pagination"><span>共{{snapshot.records.length}}条</span><button :disabled="abilityPage===1" @click="set('abilityPage',abilityPage-1)">上一页</button><span>{{abilityPage}} / {{abilityPages}}</span><button :disabled="abilityPage===abilityPages" @click="set('abilityPage',abilityPage+1)">下一页</button></div></section>
        </template>
        <template v-else>
          <nav class="student-tabs student-subtabs" aria-label="训练与任务"><button :class="{active:historyTab==='records'}" @click="set('history','records')">训练记录</button><button :class="{active:historyTab==='tasks'}" @click="set('history','tasks')">训练任务</button></nav>
          <template v-if="historyTab==='records'"><div class="student-filters"><label>时间范围<select aria-label="时间范围" :value="period" @change="set('period',$event.target.value)"><option value="30d">近30天</option><option value="90d">近90天</option><option value="semester">本学期</option></select></label><label>来源<select aria-label="来源" :value="q.trainingSource||''" @change="set('trainingSource',$event.target.value)"><option value="">全部来源</option><option value="SELF">学生自主</option><option value="TEACHER_TASK">教师任务</option></select></label><label class="student-search">训练内容<input :value="q.contentSearch||''" placeholder="搜索训练内容" @input="set('contentSearch',$event.target.value)"/></label><button :aria-expanded="trainingAdvanced" aria-controls="training-more-filters" @click="trainingAdvanced=!trainingAdvanced">更多筛选{{trainingChips.length?'（'+trainingChips.length+'）':''}}</button></div><div v-if="trainingAdvanced" id="training-more-filters" class="student-filters student-advanced"><label>训练形式<select aria-label="训练形式" :value="q.type||''" @change="set('type',$event.target.value)"><option value="">全部形式</option><option>AI虚拟面试</option><option>专项训练</option></select></label><label v-if="recordPositions.length>1">目标岗位<select aria-label="目标岗位" :value="q.trainingPosition||''" @change="set('trainingPosition',$event.target.value)"><option value="">全部岗位</option><option v-for="p in recordPositions" :key="p">{{p}}</option></select></label><span v-else class="student-static-field">目标岗位：{{recordPositions[0]||'未提供'}}</span></div><div v-if="trainingChips.length" class="student-filter-chips"><button v-for="f in trainingChips" :key="f.key" @click="set(f.key,'')" :aria-label="'移除'+f.label">{{f.label}} ×</button></div><div v-if="trainingRows.length" class="student-table-scroll"><table class="student-history-table"><thead><tr><th>训练时间</th><th>形式与目标</th><th>目标岗位</th><th>来源</th><th>有效性</th><th>本次报告评分</th><th>结果变化</th><th>报告</th><th>关联任务</th></tr></thead><tbody><tr v-for="r in pagedTraining" :key="r.id"><td>{{formatDate(r.completedAt)}}</td><td>{{r.content}}<small>{{r.type}}</small></td><td>{{r.position}}</td><td>{{r.source==='TEACHER_TASK'?'教师任务':'学生自主'}}</td><td>{{r.valid?'有效':'无效'}}</td><td>{{r.valid&&Number.isFinite(r.score)?decimal(r.score)+'分':'评分无效或缺失'}}</td><td>{{deltaLabel(r.comparison.delta,r.comparison.reason)}}</td><td><RouterLink v-if="r.reportAvailable" :to="reportLink(r)">查看报告</RouterLink><span v-else>不可访问</span></td><td><RouterLink v-if="data.tasks.some(t=>t.id===r.taskId)" :to="taskLink({id:r.taskId})">查看任务</RouterLink><span v-else>{{r.taskId?'关联任务不可用':'无关联任务'}}</span></td></tr></tbody></table></div><p v-else class="student-empty">暂无符合条件的训练记录。</p><p class="student-muted">结果变化只比较紧邻的同岗位、同模型、同版本有效报告；不能比较时说明原因。</p><div v-if="trainingRows.length" class="student-pagination"><span>共{{trainingRows.length}}条</span><button :disabled="page===1" @click="set('page',page-1)">上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page===pages" @click="set('page',page+1)">下一页</button></div></template>
          <template v-else><div v-if="q.taskAbility" class="student-filter-chips"><button @click="clearTaskFilter">{{q.taskAbility}} · 待完成任务 ×</button></div><div v-if="taskRows.length" class="student-table-scroll"><table class="student-task-table"><thead><tr><th>任务名称</th><th>类型与形式</th><th>执行状态</th><th>有效完成次数</th><th>逾期情况</th><th>最近结果</th><th>截止时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in taskRows" :key="r.task.id"><td>{{r.task.title}}</td><td>{{taskTypes[r.task.type]}}<small>{{modes[r.task.trainingMode]}}</small></td><td>{{statusNames[r.execution.completionStatus]}}</td><td>{{r.execution.validAttemptCount||0}}次<small>要求{{r.task.minValidAttempts}}次</small></td><td :class="{'student-danger':r.overdue}">{{r.overdue?'逾期未完成':r.execution.lateCompleted?'逾期完成':'未逾期'}}</td><td>{{r.evidence.latest?decimal(r.evidence.latest.score)+'分':'暂无有效结果'}}</td><td>{{formatDate(r.task.deadline)}}</td><td><RouterLink :to="taskLink(r.task)">查看任务</RouterLink></td></tr></tbody></table></div><p v-else class="student-empty">{{q.taskAbility?'暂无该能力的待完成任务，可清除筛选查看历史。':'暂无训练任务，可从顶部布置训练。'}}</p></template>
        </template>
      </template>
    </template>
  </main>
  <TeacherDrawer v-if="evidenceOpen&&student" modal class="student-evidence" :title="ability.name+' · 能力证据'" @close="evidenceOpen=false">
    <div class="student-evidence-body"><p class="student-evidence-summary">{{snapshot.current===null?'暂无有效评分':snapshot.sampleLabel+'：'+decimal(snapshot.current)+'分'}} · {{periodLabel}}</p><details class="student-calculation-details"><summary>查看计算口径与来源</summary><dl class="student-evidence-facts"><dt>岗位</dt><dd>{{abilityPosition||'未设置'}}</dd><dt>评分版本</dt><dd>{{snapshot.records.length?snapshot.version:'暂无可比版本'}}</dd><dt>计算样本</dt><dd>最近{{snapshot.calculationRecords.length}}次；当前阶段可比记录{{snapshot.records.length}}次</dd><dt>最近更新</dt><dd>{{snapshot.updatedAt?formatDate(snapshot.updatedAt):'暂无'}}</dd></dl><p>当前值采用当前连续评分阶段内最近最多3次有效评分平均。成长判定需至少6次记录，完整规则可在能力页展开查看。</p></details><h3>参与当前值计算的记录</h3><p v-if="!snapshot.calculationRecords.length" class="student-empty">当前没有足够有效记录生成能力判断。</p><ul class="student-record-list"><li v-for="r in [...snapshot.calculationRecords].reverse()" :key="r.id" :class="{'student-evidence-selected':evidenceRecord===r.id}"><div><strong>{{r.content}}</strong><p>{{formatDate(r.completedAt)}} · {{decimal(r.abilityScore)}}分 · {{r.source==='TEACHER_TASK'?'教师任务':'学生自主'}}</p><details class="student-record-source"><summary>来源详情</summary><dl><dt>训练记录</dt><dd>{{r.id}}</dd><dt>报告</dt><dd>{{r.reportId||'不可访问'}}</dd><dt>评分版本</dt><dd>{{r.version||'未说明'}}</dd></dl></details><p>与上次变化：{{deltaLabel(r.delta,'首次记录')}}</p></div><RouterLink v-if="r.reportAvailable" :to="reportLink(r)">查看报告</RouterLink><span v-else>报告不可访问</span></li></ul><details v-if="snapshot.records.length>3" :open="!!evidenceRecord&&!snapshot.calculationRecords.some(r=>r.id===evidenceRecord)"><summary>查看其他可比记录（{{snapshot.records.length-3}}条）</summary><ul class="student-record-list"><li v-for="r in [...snapshot.records.slice(0,-3)].reverse()" :key="r.id" :class="{'student-evidence-selected':evidenceRecord===r.id}"><span>{{formatDate(r.completedAt)}} · {{r.content}} · {{decimal(r.abilityScore)}}分</span><RouterLink v-if="r.reportAvailable" :to="reportLink(r)">查看报告</RouterLink></li></ul></details><template v-if="reportEvidence.length"><h3>报告表现证据</h3><section v-for="group in ['positive','improvement'].filter(g=>reportEvidence.some(e=>e.kind===g))" :key="group"><h4>{{group==='positive'?'正向表现':'待改善表现'}}</h4><blockquote v-for="e in reportEvidence.filter(e=>e.kind===group)" :key="e.record.id+e.text">{{e.text}}<footer><RouterLink :to="reportLink(e.record)">{{formatDate(e.record.completedAt)}} · 原报告</RouterLink></footer></blockquote></section></template><p v-else class="student-muted">当前报告未提供可追溯的表现证据原文，请查看原报告评分。</p><section v-if="evidenceTasks.length"><h3>关联任务</h3><p v-for="t in evidenceTasks" :key="t.id"><RouterLink :to="taskLink(t)">{{t.title}} · 查看任务</RouterLink></p></section></div><footer class="student-evidence-footer"><button @click="evidenceOpen=false">关闭</button><RouterLink v-if="abilityAction" class="student-primary" :to="abilityAction.to">{{abilityAction.label}}</RouterLink></footer>
  </TeacherDrawer></AppLayout></div>
</template>

<script setup>
import LiveStudentSupport from './LiveStudentSupport.vue'
import {normalizeTeacherQuery,teacherContext,safeTeacherReturn} from '../../services/teacherContext.js'
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppLayout from '../../components/layout/AppLayout.vue'
import TeacherDrawer from '../../components/teacher/TeacherDrawer.vue'
import StudentAbilityChart from '../../components/teacher/StudentAbilityChart.vue'
import { abilityDefinitions, classDefinitions, studentDataset, studentSummary, studentTasks, pendingTask, pendingAbilityTasks, reportComparison, abilitySnapshot, inPeriod, sourceReturn, formatDate, decimal } from '../../services/studentCenter.js'
import { membersFor, statusNames, taskTypes, modes } from '../../services/trainingTasks.js'
import '../../assets/styles/student-center.css'
const route=useRoute(),router=useRouter(),q=computed(()=>normalizeTeacherQuery(route.query)),demo=computed(()=>q.value.demo==='1'),detail=computed(()=>!!route.params.id)
const refresh=ref(0),data=computed(()=>{refresh.value;try{return studentDataset(demo.value)}catch(e){return {students:[],records:[],tasks:[],source:'error',now:Date.now(),error:e.message}}}),advanced=ref(false),trainingAdvanced=ref(false),evidenceOpen=ref(false),evidenceRecord=ref('')
const tabs=[{id:'overview',name:'概览'},{id:'ability',name:'能力成长'},{id:'training',name:'训练与任务'}],growthStatuses=['有效提升','基本稳定','轻微下降','持续下降','数据不足']
const tab=computed(()=>tabs.some(t=>t.id===q.value.tab)?q.value.tab:'overview'),historyTab=computed(()=>q.value.history==='tasks'?'tasks':'records')
const student=computed(()=>data.value.students.find(s=>s.id===route.params.id)),summary=computed(()=>student.value?studentSummary(data.value,student.value,q.value):null)
const periodLabel=computed(()=>q.value.from?`${q.value.from}～${q.value.to}`:period.value==='7d'?'近7天':period.value==='30d'?'近30天':period.value==='90d'?'近90天':'本学期')
const period=computed(()=>['7d','30d','90d','semester'].includes(q.value.period)?q.value.period:'30d'),scope=computed(()=>q.value.scope==='role'||q.value.scope==='specialty'||!q.value.scope&&abilityDefinitions.some(a=>a.scope==='role'&&(a.id===q.value.ability||a.name===q.value.ability))?'role':'common')
const ability=computed(()=>abilityDefinitions.find(a=>a.scope===scope.value&&(a.id===q.value.ability||a.name===q.value.ability))||abilityDefinitions.find(a=>a.scope===scope.value))
const positions=computed(()=>[...new Set(data.value.students.map(s=>s.position).filter(Boolean))])
const allRows=computed(()=>data.value.students.filter(s=>!s.legacy).map(s=>studentSummary(data.value,s,q.value)))
const rows=computed(()=>{
  const query=q.value,search=String(query.search||'').trim().toLowerCase()
  return allRows.value.filter(s=>(!query.analyticsActive||s.account==='normal')&&(!query.classId||s.classId===query.classId)&&(!query.classIds||String(query.classIds).split(',').includes(s.classId))&&(!query.position||s.position===query.position)&&(!search||(s.name+s.number).toLowerCase().includes(search))&&(!query.growth||s.growth.status===query.growth)&&(!query.concern||(query.concern==='overdue'?s.overdueCount>0:s.count<2))&&(!query.recent||(query.recent==='none'?s.count===0:s.last&&data.value.now-Date.parse(s.last)<=Number(query.recent)*86400000))).sort((a,b)=>query.sort==='name'?a.name.localeCompare(b.name,'zh-CN'):query.sort==='count'?b.count-a.count:query.sort==='recent'?(Date.parse(b.last)||0)-(Date.parse(a.last)||0):a.attentionRank-b.attentionRank||(Date.parse(a.last)||0)-(Date.parse(b.last)||0)||a.number.localeCompare(b.number))
})
const filterChips=computed(()=>[['position',q.value.position],['recent',q.value.recent==='none'?'当前周期无有效训练':q.value.recent?'近'+q.value.recent+'天有有效训练':''],['growth',q.value.growth],['concern',q.value.concern==='overdue'?'有逾期任务':q.value.concern?'训练不足2次':'']].filter(([key,label])=>q.value[key]&&label).map(([key,label])=>({key,label})))
const recentRecords=computed(()=>data.value.records.filter(r=>r.studentId===student.value?.id&&Date.parse(r.completedAt)<=data.value.now).sort((a,b)=>Date.parse(b.completedAt)-Date.parse(a.completedAt)))
const recordPositions=computed(()=>[...new Set(recentRecords.value.map(r=>r.position))]),historicalPositions=computed(()=>recordPositions.value.filter(p=>p!==student.value?.position))
const abilityPosition=computed(()=>recordPositions.value.includes(q.value.abilityPosition)?q.value.abilityPosition:student.value?.position)
const snapshot=computed(()=>student.value?abilitySnapshot(data.value,student.value,ability.value,{...q.value,period:period.value},abilityPosition.value):null)
const commonSnapshots=computed(()=>student.value?abilityDefinitions.filter(a=>a.scope==='common').map(a=>abilitySnapshot(data.value,student.value,a,q.value)):[])
const focusSnapshot=computed(()=>commonSnapshots.value.filter(s=>s.current!==null&&s.target!==null).sort((a,b)=>a.gap-b.gap)[0])
const abilityConcern=computed(()=>focusSnapshot.value?.gap<0?`${focusSnapshot.value.ability.name} ${decimal(focusSnapshot.value.current)} / ${focusSnapshot.value.target}，低于演示目标 ${Math.abs(focusSnapshot.value.gap).toFixed(1)} 分。`:commonSnapshots.value.some(s=>s.current!==null)?'当前没有明确低于已配置目标的能力。':'暂无足够训练数据，暂不能判断能力水平。')
const tasks=computed(()=>studentTasks(data.value,student.value?.id)),currentTasks=computed(()=>tasks.value.filter(r=>pendingTask(r,data.value.now)))
const focusPending=computed(()=>focusSnapshot.value?pendingAbilityTasks(data.value,student.value?.id,focusSnapshot.value.ability.name):[])
const abilityPending=computed(()=>pendingAbilityTasks(data.value,student.value?.id,ability.value.name))
const taskRows=computed(()=>q.value.taskAbility?tasks.value.filter(r=>r.task.type==='ABILITY'&&r.task.primaryAbility===q.value.taskAbility&&pendingTask(r,data.value.now)):tasks.value)
const abilityAction=computed(()=>abilityPending.value.length?{label:'查看已有任务（'+abilityPending.value.length+'）',to:existingTasksLink(abilityPending.value,ability.value)}:canCreate.value&&scope.value==='common'?{label:'布置'+ability.value.name+'训练',to:createLink(ability.value)}:null)
const headerAction=computed(()=>tab.value==='ability'?(abilityAction.value|| (canCreate.value?{label:'布置岗位训练',to:createLink()}:null)):canCreate.value?{label:'布置训练',to:createLink()}:null)
const canCreate=computed(()=>!!student.value&&membersFor(student.value.classId).some(s=>s.id===student.value.id&&s.eligible))
const trainingRows=computed(()=>{
  const chronological=[...recentRecords.value].reverse()
  return chronological.map((r,i)=>({...r,comparison:reportComparison(r,chronological[i-1])})).reverse().filter(r=>inPeriod(r,q.value,data.value.now)&&(!q.value.trainingSource||r.source===q.value.trainingSource)&&(!q.value.type||r.type===q.value.type)&&(!q.value.trainingPosition||r.position===q.value.trainingPosition)&&(!q.value.contentSearch||r.content.toLowerCase().includes(String(q.value.contentSearch).toLowerCase())))
})
const pages=computed(()=>Math.max(1,Math.ceil((detail.value?trainingRows.value.length:rows.value.length)/15))),page=computed(()=>Math.min(pages.value,Math.max(1,Number(q.value.page)||1)))
const abilityPages=computed(()=>Math.max(1,Math.ceil((snapshot.value?.records.length||0)/15))),abilityPage=computed(()=>Math.min(abilityPages.value,Math.max(1,Number(q.value.abilityPage)||1)))
const pagedAbilityRecords=computed(()=>[...(snapshot.value?.records||[])].reverse().slice((abilityPage.value-1)*15,abilityPage.value*15))
const trainingChips=computed(()=>[['type',q.value.type],['trainingPosition',q.value.trainingPosition]].filter(([key,label])=>label).map(([key,label])=>({key,label})))
const pagedRows=computed(()=>rows.value.slice((page.value-1)*15,page.value*15)),pagedTraining=computed(()=>trainingRows.value.slice((page.value-1)*15,page.value*15))
const returnInfo=computed(()=>sourceReturn(q.value)),returnLink=computed(()=>returnInfo.value.path.includes('?')?returnInfo.value.path:{path:returnInfo.value.path,query:{...returnInfo.value.query,demo:demo.value?'1':undefined,insights:q.value.insights}})
const recordsLink=computed(()=>link('/teacher/training-records',{student:student.value?.id,classId:student.value?.legacy?undefined:student.value?.classId,insights:student.value?.legacy?undefined:'1',returnTo:route.fullPath}))
const reportEvidence=computed(()=>snapshot.value?.records.flatMap(record=>(record.evidence||[]).filter(e=>e.abilityId===ability.value.id&&typeof e.text==='string'&&e.text.trim()&&['positive','improvement'].includes(e.kind)&&e.reportId===record.reportId&&e.trainingRecordId===record.id).map(e=>({...e,record})))||[])
const evidenceTasks=computed(()=>data.value.tasks.filter(t=>snapshot.value?.records.some(r=>r.taskId===t.id)))
function link(path,extra={}){return {path,query:{demo:demo.value?'1':undefined,...extra}}}
function set(key,value){const query={...q.value,[key]:value||undefined,page:key==='page'?value:undefined,abilityPage:key==='abilityPage'?value:undefined};if(key==='period'){for(const k of ['from','to','analyticsFrom','analyticsTo','timeRange'])delete query[k]}router.replace({query})}
function clearFilters(){router.replace({query:{demo:demo.value?'1':undefined}})}
function studentLink(s){return link(`/teacher/students/${s.id}`,{tab:'overview',returnTo:route.fullPath,classId:s.classId,insights:s.legacy?undefined:'1'})}
function reportLink(r){return link(`/teacher/reports/${r.reportId}`,{insights:r.id.startsWith('ci-')?'1':undefined,classId:r.classId,returnTo:route.fullPath,returnStudent:student.value?.id})}
function taskLink(t){return link(`/teacher/tasks/${t.id}`,{sourceStudentId:student.value?.id,returnStudent:student.value?.id,returnTo:route.fullPath})}
function createLink(a){return link('/teacher/tasks/create',{classId:student.value?.classId,students:student.value?.id,ability:a?.name,source:a?'studentAbility':'studentOverview',returnStudent:student.value?.id,returnTo:route.fullPath})}
function selectAbility(id){const a=abilityDefinitions.find(a=>a.id===id);if(a)router.replace({query:{...q.value,ability:a.id,scope:a.scope,page:undefined,abilityPage:undefined}})}
function existingTasksLink(rows,a){return rows.length===1?taskLink(rows[0].task):link(route.path,{...q.value,tab:'training',history:'tasks',taskAbility:a.name,page:undefined})}
function clearTaskFilter(){router.replace({query:{...q.value,taskAbility:undefined}})}
function chooseAbility(id){router.replace({query:{...q.value,tab:'ability',ability:id,scope:'common',page:undefined}})}
function showTasks(){router.replace({query:{...q.value,tab:'training',history:'tasks',taskAbility:undefined,page:undefined}})}
function selectEvidence(id){evidenceRecord.value=id;evidenceOpen.value=true}
function gapLabel(s){return s.target===null?'未设置目标':s.current===null?'暂无有效评分':s.gap<0?'低于 '+Math.abs(s.gap).toFixed(1)+'分':s.gap>0?'高于 '+s.gap.toFixed(1)+'分':'达到目标'}
function deltaLabel(n,reason='暂无可比评分'){return Number.isFinite(n)?(n>0?'+':'')+n.toFixed(1)+'分':reason}
watch(()=>route.fullPath,()=>{evidenceOpen.value=false;evidenceRecord.value=''})
</script>
